-- =====================================================================
-- NorthWest — Collection Summary Aggregates
-- Pre-computes the data behind the 13 Collection Summary tabs in the
-- LabMetricsDashboard web app.  Generated by _GenerateCollectionSummary.ps1.
-- All SPs are idempotent (TRUNCATE + INSERT) and safe to re-run.
--
-- Per-lab settings:
--   Panel column        = PanelType
--   Has BilledUnbilled  = False
--   Has AgingBucket     = False
-- =====================================================================

SET NOCOUNT ON;
GO

